from fractions import Fraction
from math import isfinite
from numbers import Real


class MonotoneRisk:
    def __init__(self, scores):
        try:
            values = list(scores)
        except TypeError as exc:
            raise TypeError("scores must be iterable") from exc

        checked = []
        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("each score must be a real number")
            try:
                number = float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("each score must be a finite real number") from exc
            if not isfinite(number) or not 0.0 <= number <= 1.0:
                raise ValueError("each score must be finite and between 0 and 1")
            checked.append(value)
        self._scores = tuple(sorted(checked))

    @property
    def scores(self):
        return self._scores

    def reverse_rank(self):
        for index in range(len(self._scores) - 1, -1, -1):
            yield index, self._scores[index]

    def raw_levels(self):
        count = len(self._scores)
        result = []
        for index, score in enumerate(self._scores):
            exact_score = Fraction(str(score))
            level = min(Fraction(1), exact_score * count / (index + 1))
            result.append(float(level))
        return result

    def adjusted_levels(self):
        raw = self.raw_levels()
        result = [0.0] * len(raw)
        running = 1.0
        for index in range(len(raw)):
            running = min(running, raw[index])
            result[index] = running
        return result

